11 		public static MapAtlasInterpreter Singleton { get; private set; }
12 
13 		public AtlasInterpretation[] Interpret(Texture2D atlas, System.Random rng)
14 		{
15 			MapAtlasInterpreter.ResultsBuffer.Clear();
16 			if (!atlas.isReadable)
17 			{
18 				throw new InvalidOperationException("Provided atlas '" + atlas.name + "' is not marked as readable. Please change the import settings in editor.");
19 			}
20 			int num = 1;
21 			int num2 = 0;
22 			bool flag = false;
23 			for (int i = 0; i < atlas.height; i += num)
24 			{
25 				for (int j = num2; j < atlas.width; j += num)
26 				{
27 					GlyphShapePair? glyphShapePair = this.ScanPixel(atlas, j, i);
28 					if (glyphShapePair != null)
29 					{
30 						if (!flag)
31 						{
32 							Vector2Int glyphCenterOffset = glyphShapePair.Value.GlyphCenterOffset;
33 							j += glyphCenterOffset.x;
34 							i += glyphCenterOffset.y;
35 							num = 3;
36 							num2 = j % 3;
37 							flag = true;
38 						}
39 						MapAtlasInterpreter.ResultsBuffer.Add(new AtlasInterpretation(glyphShapePair.Value, rng, j, i));
40 					}
41 				}
42 			}
43 			return MapAtlasInterpreter.ResultsBuffer.ToArray();
44 		}
45 
46 		private GlyphShapePair? ScanPixel(Texture2D atlas, int x, int y)
47 		{
48 			Color32 color = atlas.GetPixel(x, y);
49 			foreach (GlyphShapePair glyphShapePair in this.PairDefinitions)
50 			{
51 				if (Mathf.Abs((int)(glyphShapePair.GlyphColor.r - color.r)) <= 5 && Mathf.Abs((int)(glyphShapePair.GlyphColor.g - color.g)) <= 5 && Mathf.Abs((int)(glyphShapePair.GlyphColor.b - color.b)) <= 5)
52 				{
53 					return new GlyphShapePair?(glyphShapePair);
54 				}
55 			}
56 			return null;
57 		}
58 
59 		private void Awake()
60 		{
61 			MapAtlasInterpreter.Singleton = this;
62 		}
63 
64 		private static readonly List<AtlasInterpretation> ResultsBuffer = new List<AtlasInterpretation>();
